def __transform_coors(coor, i, j, xstride, ystride):
    x1, y1, x2, y2 = coor

    dx = x2 - x1
    dy = y2 - y1
    A = dx * dy

    # Def some functions
    def inframe(e, stride, n): return e // stride == n

    def new_e(e, stride): return e % stride

    if (inframe(x1, xstride, i) and inframe(y1, ystride, j)) \
       or (inframe(x2, xstride, i) and inframe(y2, ystride, j)):

        if inframe(x1, xstride, i):
            x1_prime = int(new_e(x1, xstride))
        else:
            x1_prime = 0

        if inframe(y1, ystride, j):
            y1_prime = int(new_e(y1, ystride))
        else:
            y1_prime = 0

        if inframe(x2, xstride, i):
            x2_prime = int(new_e(x2, xstride))
        else:
            x2_prime = xstride

        if inframe(y2, ystride, j):
            y2_prime = int(new_e(y2, ystride))
        else:
            y2_prime = ystride

        dx_prime = x2_prime - x1_prime
        dy_prime = y2_prime - y1_prime
        A_prime = dx_prime * dy_prime

        # Save the feature if the box is valid, and if the area of the box
        # is at least 40% of the original object area
        if (x2 > x1) and (y2 > y1) and (A_prime > .4 * A):
            return (x1_prime, y1_prime, x2_prime, y2_prime)


def transform_coors(coor, i, j, xstride, ystride):
    """Public entry point for coordinate transformation.

    Delegates to the internal implementation while exposing a stable,
    importable symbol matching the module name.
    """
    return __transform_coors(coor, i, j, xstride, ystride)

